import 'package:flutter/foundation.dart';
import 'package:opfan/core/errors/app_exceptions.dart';
import 'package:opfan/core/services/image_host/i_image_host_service.dart';

import 'i_gemini_client.dart';
import 'i_gemini_service.dart';

/// Sanji's text and the character / crew images, generated by Gemini through
/// Firebase AI Logic. Every failure returns `null`, which callers already treat
/// as "no AI result"; a used-up free tier also pauses calls for
/// [_quotaCooldown].
class GeminiService implements IGeminiService {
  GeminiService({required this._client, required this._imageHost});

  final IGeminiClient _client;
  final IImageHostService _imageHost;

  static const String _textModel = 'gemini-2.5-flash-lite';
  static const String _imageModel = 'gemini-2.5-flash-image';
  static const Duration _quotaCooldown = Duration(minutes: 2);

  final Map<String, String> _imageCache = {};
  DateTime? _cooldownUntil;

  bool get _inCooldown {
    final until = _cooldownUntil;
    return until != null && DateTime.now().isBefore(until);
  }

  @override
  Future<String?> generateText({
    required String prompt,
    String? systemInstruction,
    String? context,
    double? temperature,
    int? topK,
    double? topP,
    int? maxOutputTokens,
  }) async {
    if (_inCooldown) return null;
    final text = await _guard(
      'text',
      () => _client.generateText(
        model: _textModel,
        prompt: _withContext(prompt, context),
        systemInstruction:
            systemInstruction == null || systemInstruction.isEmpty
            ? null
            : systemInstruction,
        temperature: temperature ?? 0.4,
        topK: topK ?? 40,
        topP: topP ?? 0.95,
        maxOutputTokens: maxOutputTokens ?? 8192,
      ),
    );
    return text == null || text.isEmpty ? null : text;
  }

  // Callers write their own detailed prompts; only the optional context is
  // prepended, never generic suffixes that would contradict them.
  String _withContext(String prompt, String? context) =>
      context == null || context.isEmpty
      ? prompt
      : 'Context: $context\n\n$prompt';

  @override
  Future<String?> generateImage({
    required String prompt,
    bool forceRefresh = false,
  }) async {
    final cacheKey = prompt.hashCode.toString();
    if (!forceRefresh && _imageCache.containsKey(cacheKey)) {
      return _imageCache[cacheKey];
    }
    if (_inCooldown) return null;

    final png = await _guard(
      'image',
      () => _client.generateImage(model: _imageModel, prompt: prompt),
    );
    if (png == null) return null;

    final url = await _imageHost.upload(png);
    _imageCache[cacheKey] = url;
    return url;
  }

  Future<T?> _guard<T>(String kind, Future<T?> Function() call) async {
    try {
      return await call();
    } on QuotaExceededException {
      debugPrint('Gemini Service: $kind quota exceeded, pausing');
      _cooldownUntil = DateTime.now().add(_quotaCooldown);
      return null;
    } catch (e) {
      debugPrint('Gemini Service: $kind generation failed - $e');
      return null;
    }
  }
}
